                                            const int height, const int width, 
                                            const int stride, const int padding, 
                                            const int groups, const bool bias) {
                // Calculate the output shape
                int out_height = (height + 2 * padding - stride) // stride + 1
                int out_width = (width + 2 * padding - stride) // stride + 1

                int total_elements = in_channels * out_channels * out_height * out_width
